 # Across cells, only literal CONFIG and two constructor defaults differ.
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets): n.value=ast.Constant(None)
